Функция ПроверитьРедакцию()
    Данные = Новый Структура;
    Если Не Данные.Свойство("Редакция") Тогда
        Возврат "нет";
    КонецЕсли;
    Возврат "есть";
КонецФункции

Функция СостояниеПереключателя()
    Перем ЗначениеПереключателя;
    Данные = Новый Структура("Переключатель", Ложь);
    Если Не Данные.Свойство("Переключатель", ЗначениеПереключателя) Тогда
        Возврат "нет";
    КонецЕсли;
    Если ЗначениеПереключателя Тогда
        Возврат "включен";
    КонецЕсли;
    Возврат "выключен";
КонецФункции

Функция ОбработатьДанные(Данные)
    Если ТипЗнч(Данные) <> Тип("Структура") Тогда
        Возврат Ложь;
    КонецЕсли;
    Если Не Данные.Свойство("ДатаНачала") Или Не Данные.Свойство("ДатаНачала") Тогда
        Возврат Ложь;
    КонецЕсли;
    Если ТипЗнч(Данные.ДатаНачала) <> Тип("Дата") Или ТипЗнч(Данные.ДатаОкончания) <> Тип("Дата") Тогда
        Возврат Ложь;
    КонецЕсли;
    Возврат Данные.ДатаНачала <= Данные.ДатаОкончания;
КонецФункции

